$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Drawing
$root = (Resolve-Path "$PSScriptRoot/../../..").Path
$source = @'
using System;
using System.IO;
using System.Drawing;
using System.Drawing.Imaging;
using System.Drawing.Drawing2D;
using System.Drawing.Text;
using System.Collections.Generic;
public static class K090 {
 static string Dir,Root; static Bitmap Tex; static List<string> Records=new List<string>();
 static Color Ink=Color.FromArgb(10,14,13), Brass=Color.FromArgb(177,143,78), Light=Color.FromArgb(236,208,145);
 static Bitmap B(int w,int h){return new Bitmap(w,h,PixelFormat.Format32bppArgb);}
 static Graphics G(Bitmap b){var g=Graphics.FromImage(b);g.SmoothingMode=SmoothingMode.None;g.InterpolationMode=InterpolationMode.NearestNeighbor;g.PixelOffsetMode=PixelOffsetMode.Half;return g;}
 static Bitmap Scale(Bitmap b,int n){var o=B(b.Width*n,b.Height*n);using(var g=G(o))g.DrawImage(b,new Rectangle(0,0,o.Width,o.Height),0,0,b.Width,b.Height,GraphicsUnit.Pixel);return o;}
 static void Save(Bitmap b,string name,bool preview){b.Save(Path.Combine(Dir,name+".png"),ImageFormat.Png);Records.Add(name+"\t"+b.Width+"\t"+b.Height);if(preview){using(var p=Scale(b,4))p.Save(Path.Combine(Dir,"previews",name+"_4x.png"),ImageFormat.Png);}}
 static void Asset(Bitmap native,string name){Save(native,"native/"+name,false);using(var game=Scale(native,3))Save(game,name,true);}
 static Color Wood(int x,int y,int state){var t=Tex.GetPixel((x*Tex.Width/120)%Tex.Width,(y*Tex.Height/120)%Tex.Height);int q=(t.R+t.G+t.B)/3;int v=q<24?0:q<37?1:2;if(state==2)return Color.FromArgb(22+v*3,26+v*3,24+v*3);return state==1?Color.FromArgb(49+v*7,49+v*6,35+v*3):Color.FromArgb(24+v*6,28+v*5,24+v*3);}
 static double Angle(double dx,double dy){return Math.Atan2(dy,dx)*180/Math.PI;}
 static double Diff(double a,double b){return Math.Abs((a-b+540)%360-180);}
 static Bitmap Wedge(int n,double inner,double outer,int count,int index,int state){var b=B(n,n);double c=(n-1)/2.0, mid=-90+index*360.0/count;for(int y=0;y<n;y++)for(int x=0;x<n;x++){double dx=x-c,dy=y-c,r=Math.Sqrt(dx*dx+dy*dy),d=Diff(Angle(dx,dy),mid),a=180.0/count-2.0;if(r<inner||r>outer||d>a)continue;double edge=(a-d)*Math.PI/180*r;Color col=Wood(x,y,state);if(r<inner+1||r>outer-1||edge<1)col=Ink;else if(r<inner+2||r>outer-2||edge<2)col=state==2?Color.FromArgb(68,71,61):state==1?Light:Brass;else if(r>outer-3&&dy<0)col=state==2?Color.FromArgb(45,49,44):Color.FromArgb(103,87,51);b.SetPixel(x,y,col);}if(state==2){int sx=(int)Math.Round(c+Math.Cos(mid*Math.PI/180)*(outer-5)),sy=(int)Math.Round(c+Math.Sin(mid*Math.PI/180)*(outer-5));using(var g=G(b)){Line(g,Ink,sx-2,sy-2,sx+2,sy+2,3);Line(g,Color.FromArgb(112,114,94),sx-2,sy-2,sx+2,sy+2,1);}}return b;}
 static void CenterText(Bitmap b,string s,float size,Color color,int cx,int cy){using(var g=G(b))using(var f=new Font("Malgun Gothic",size,FontStyle.Bold,GraphicsUnit.Pixel))using(var brush=new SolidBrush(color))using(var sh=new SolidBrush(Ink)){g.TextRenderingHint=TextRenderingHint.SingleBitPerPixelGridFit;var fmt=new StringFormat{Alignment=StringAlignment.Center,LineAlignment=StringAlignment.Center};g.DrawString(s,f,sh,new PointF(cx+1,cy+1),fmt);g.DrawString(s,f,brush,new PointF(cx,cy),fmt);}}
 static Bitmap Load(string name){return new Bitmap(Path.Combine(Dir,name+".png"));}
 static void Put(Bitmap dest,string name,int x,int y){using(var b=Load(name))using(var g=G(dest))g.DrawImageUnscaled(b,x,y);}
 static void PutSize(Bitmap dest,string file,int x,int y,int w,int h){using(var b=new Bitmap(file))using(var g=G(dest))g.DrawImage(b,new Rectangle(x,y,w,h));}
 static void NativeSheet(string name,string[] columns,string[] states,int cell){using(var b=B(cell*columns.Length,cell*states.Length)){using(var g=G(b))for(int s=0;s<states.Length;s++)for(int i=0;i<columns.Length;i++)using(var a=Load("native/"+name+"_"+columns[i]+"_"+states[s]))g.DrawImageUnscaled(a,i*cell,s*cell);Save(b,"native/"+name+"_states_sheet",false);}}
 static void Line(Graphics g,Color c,int x1,int y1,int x2,int y2,int width){using(var p=new Pen(c,width))g.DrawLine(p,x1,y1,x2,y2);}
 static Bitmap Arrow(int d){var b=B(9,7);using(var g=G(b)){Point[] pts={new Point(4,0),new Point(8,4),new Point(6,4),new Point(6,6),new Point(2,6),new Point(2,4),new Point(0,4)};g.FillPolygon(new SolidBrush(Ink),pts);Point[] face={new Point(4,1),new Point(7,4),new Point(5,4),new Point(5,5),new Point(3,5),new Point(3,4),new Point(1,4)};g.FillPolygon(new SolidBrush(Brass),face);}if(d==1)b.RotateFlip(RotateFlipType.Rotate90FlipNone);if(d==2)b.RotateFlip(RotateFlipType.Rotate180FlipNone);if(d==3)b.RotateFlip(RotateFlipType.Rotate270FlipNone);return b;}
 static void Flag(Graphics g,int x,int y,int half,bool dim){Color cloth=dim?Color.FromArgb(88,89,72):Color.FromArgb(189,152,77);Line(g,Ink,x,y,x,y+13,3);Line(g,Light,x,y,x,y+12,1);using(var br=new SolidBrush(Ink))g.FillPolygon(br,new[]{new Point(x+1,y),new Point(x+11,y+1),new Point(x+9,y+5),new Point(x+11,y+9),new Point(x+1,y+8)});using(var br=new SolidBrush(cloth))g.FillRectangle(br,x+1,y+1,8,6);if(half==1)using(var br=new SolidBrush(Color.FromArgb(48,55,46)))g.FillRectangle(br,x+5,y+1,4,6);Line(g,Color.FromArgb(104,78,41),x+2,y+6,x+8,y+6,1);}
 static Bitmap Ring(string state){var b=B(222,222);Put(b,"direction_base",0,0);string[] ds={"north","east","south","west"};for(int i=0;i<4;i++)Put(b,"direction_"+ds[i]+"_"+(state=="all_disabled"?"disabled":state==ds[i]?"hover":"normal"),0,0);Put(b,"direction_hub",66,66);CenterText(b,"40명",22,Light,111,111);int[,] lp={{111,46},{176,111},{111,176},{46,111}};int[,] ap={{111,20},{202,111},{111,202},{20,111}};for(int i=0;i<4;i++){using(var l=Load("compass_"+ds[i]))using(var g=G(b))g.DrawImageUnscaled(l,lp[i,0]-l.Width/2,lp[i,1]-l.Height/2);if(state!="all_disabled")using(var a=Load("pointer_"+ds[i]))using(var g=G(b))g.DrawImageUnscaled(a,ap[i,0]-a.Width/2,ap[i,1]-a.Height/2);}return b;}
 static Bitmap Amount(int hover){var b=B(360,360);string[] names={"one","half","all"};string[] labels={"1분대 보내기","1/2 보내기","전체 보내기"};int[,] pos={{180,75},{264,235},{96,235}};for(int i=0;i<3;i++){Put(b,"amount_"+names[i]+"_"+(hover==i?"hover":hover==3?"disabled":"normal"),0,0);Put(b,"icon_"+names[i],pos[i,0]-27,pos[i,1]-39);CenterText(b,labels[i],24,i==hover?Light:Color.FromArgb(220,218,192),pos[i,0],pos[i,1]+24);PutSize(b,Path.Combine(Root,"Game/Assets/_Project/Art/UI/Resources/HudArt/Command/command_number_"+(i+1)+".png"),pos[i,0]-12,pos[i,1]+42,24,24);if(i==hover)PutSize(b,Path.Combine(Root,"Game/Assets/_Project/Art/UI/Resources/HudArt/Command/command_underline.png"),pos[i,0]-59,pos[i,1]+37,118,5);}Put(b,"amount_hub",141,141);CenterText(b,"병력",20,Light,180,180);return b;}
 static void Select(Bitmap b,int x,int y,int w,int h){for(int i=24;i<w-24;i+=24){Put(b,"selection_dash_h",x+i,y);Put(b,"selection_dash_h",x+i,y+h-6);}for(int j=24;j<h-24;j+=24){Put(b,"selection_dash_v",x,y+j);Put(b,"selection_dash_v",x+w-6,y+j);}Put(b,"selection_corner_tl",x,y);Put(b,"selection_corner_tr",x+w-24,y);Put(b,"selection_corner_br",x+w-24,y+h-24);Put(b,"selection_corner_bl",x,y+h-24);}
 static void Caption(Bitmap b,string title,string sub){using(var g=G(b))using(var br=new SolidBrush(Color.FromArgb(225,10,14,13)))g.FillRectangle(br,32,922,1856,126);CenterText(b,title,30,Light,960,958);CenterText(b,sub,22,Color.FromArgb(222,221,206),960,1006);}
 static Bitmap Background(bool night){var b=B(1920,1080);if(!night)PutSize(b,Path.Combine(Root,"Docs/References/codex_k020_v1/reference_map.png"),0,0,1920,1080);else{using(var s=new Bitmap(Path.Combine(Root,"Docs/References/night_levels_20261020.png")))using(var g=G(b))g.DrawImage(s,new Rectangle(0,0,1920,1080),new Rectangle(s.Width/2,0,s.Width/2,s.Height/2),GraphicsUnit.Pixel);}return b;}
 public static void Run(string root){Root=root;Dir=Path.Combine(root,"Docs/References/codex_k090_v1");Directory.CreateDirectory(Path.Combine(Dir,"native"));Directory.CreateDirectory(Path.Combine(Dir,"previews"));Tex=new Bitmap(Path.Combine(Dir,"wood_source.png"));string[] states={"normal","hover","disabled"},dirs={"north","east","south","west"},amounts={"one","half","all"};
 for(int i=0;i<4;i++)for(int s=0;s<3;s++)using(var b=Wedge(74,16,36,4,i,s))Asset(b,"direction_"+dirs[i]+"_"+states[s]);
 using(var b=B(74,74)){for(int y=0;y<74;y++)for(int x=0;x<74;x++){double r=Math.Sqrt((x-36.5)*(x-36.5)+(y-36.5)*(y-36.5));if(r>=13&&r<=36.8)b.SetPixel(x,y,Ink);}Asset(b,"direction_base");}
 foreach(string type in new[]{"direction","amount"}){int n=type=="direction"?30:26;using(var b=B(n,n)){for(int y=0;y<n;y++)for(int x=0;x<n;x++){double r=Math.Sqrt(Math.Pow(x-(n-1)/2.0,2)+Math.Pow(y-(n-1)/2.0,2));if(r>n/2.0-1)continue;b.SetPixel(x,y,r>n/2.0-2?Ink:r>n/2.0-3?Brass:Wood(x,y,0));}Asset(b,type+"_hub");}}
 string[] letters={"북","동","남","서"};for(int i=0;i<4;i++){using(var b=B(36,36)){CenterText(b,letters[i],26,Light,18,18);Save(b,"compass_"+dirs[i],true);}using(var a=Arrow(i))Asset(a,"pointer_"+dirs[i]);}
 for(int i=0;i<3;i++)for(int s=0;s<3;s++)using(var b=Wedge(120,15,59,3,i,s))Asset(b,"amount_"+amounts[i]+"_"+states[s]);
 for(int i=0;i<3;i++)using(var b=B(18,17)){using(var g=G(b)){if(i==2){Flag(g,2,4,0,true);Flag(g,8,1,0,false);Flag(g,13,5,0,false);}else Flag(g,4,1,i,false);}Asset(b,"icon_"+amounts[i]);}
 using(var b=B(8,8)){using(var g=G(b)){Line(g,Ink,0,0,7,0,3);Line(g,Ink,0,0,0,7,3);Line(g,Brass,1,1,7,1,1);Line(g,Brass,1,1,1,7,1);b.SetPixel(1,1,Light);}string[] cs={"tl","tr","br","bl"};for(int i=0;i<4;i++){Asset(b,"selection_corner_"+cs[i]);b.RotateFlip(RotateFlipType.Rotate90FlipNone);}}
 using(var b=B(8,2)){for(int x=0;x<5;x++){b.SetPixel(x,0,Light);b.SetPixel(x,1,Ink);}Asset(b,"selection_dash_h");b.RotateFlip(RotateFlipType.Rotate90FlipNone);Asset(b,"selection_dash_v");}
 using(var b=B(24,10)){using(var g=G(b)){using(var p=new Pen(Ink,3))g.DrawEllipse(p,1,1,21,7);using(var p=new Pen(Brass,1))g.DrawEllipse(p,1,1,21,7);Line(g,Light,8,8,15,8,1);}Asset(b,"selected_flag_ring");}
 using(var b=B(888,666)){for(int s=0;s<3;s++)for(int i=0;i<4;i++)Put(b,"direction_"+dirs[i]+"_"+states[s],i*222,s*222);Save(b,"direction_states_sheet",true);}
 using(var b=B(1080,1080)){for(int s=0;s<3;s++)for(int i=0;i<3;i++)Put(b,"amount_"+amounts[i]+"_"+states[s],i*360,s*360);Save(b,"amount_states_sheet",true);}
 NativeSheet("direction",dirs,states,74);NativeSheet("amount",amounts,states,120); foreach(string d in dirs)using(var b=Ring(d))Save(b,"preview_direction_"+d,false);using(var b=Ring("all_disabled"))Save(b,"preview_direction_disabled",false);
 for(int i=0;i<4;i++)using(var b=Amount(i))Save(b,"preview_amount_"+i,false);
 foreach(bool night in new[]{false,true}){string suffix=night?"_night":"";using(var b=Background(night)){for(int i=0;i<4;i++){int x=night?680+i*92:820+i*60,y=night?620:275;Put(b,"selected_flag_ring",x-24,y+27);Put(b,"icon_one",x,y);}Select(b,night?655:796,night?600:250,night?410:300,135);using(var r=Ring("east"))using(var g=G(b))g.DrawImageUnscaled(r,night?1040:1080,night?500:355);Caption(b,"① Shift + 왼쪽 끌기 → 버튼을 놓으면 → 동서남북 고르기","선택한 4분대 · 40명 / 위 북 · 오른쪽 동 · 아래 남 · 왼쪽 서");Save(b,"mockup_a_selection_direction"+suffix,false);}using(var b=Background(night)){using(var a=Amount(1))using(var g=G(b))g.DrawImageUnscaled(a,night?650:780,night?370:340);Caption(b,"② 성벽 왼쪽 누르기 → 보낼 병력 고르기","1분대 보내기 / 1/2 보내기 / 전체 보내기 · 이어서 같은 동서남북 바퀴");Save(b,"mockup_b1_amount"+suffix,false);}using(var b=Background(night)){using(var r=Ring("south"))using(var g=G(b))g.DrawImageUnscaled(r,night?719:849,night?439:409);Caption(b,"③ 병력을 고른 자리 → 같은 동서남북 바퀴","가운데 40명은 표시 예시입니다. 실제 인원 계산과 명령 연결은 게임에서 처리합니다.");Save(b,"mockup_b2_direction"+suffix,false);}}
 using(var b=B(1100,650)){using(var g=G(b))g.Clear(Color.FromArgb(29,34,31));using(var r=Ring("east"))using(var g=G(b))g.DrawImageUnscaled(r,80,170);using(var a=Amount(1))using(var g=G(b))g.DrawImageUnscaled(a,370,110);Select(b,800,210,210,150);Put(b,"selected_flag_ring",848,291);Put(b,"icon_one",872,264);CenterText(b,"분대 명령 · 원형 UI",32,Light,550,50);CenterText(b,"방향 · 222점",24,Light,191,440);CenterText(b,"병력 · 360점",24,Light,550,500);CenterText(b,"상자 선택",24,Light,905,440);Save(b,"overview",true);}
 File.WriteAllLines(Path.Combine(Dir,"asset_index.tsv"),Records.ToArray(),new System.Text.UTF8Encoding(false));Tex.Dispose();
 }
}
'@
Add-Type -TypeDefinition $source -ReferencedAssemblies System.Drawing
[K090]::Run($root)
Write-Output 'K-090 에셋 생성 완료'
